WITH enriched AS (SELECT *, NTILE(4) OVER (PARTITION BY product_id, store_id ORDER BY quantity DESC, id) AS quantity_bucket, PERCENT_RANK() OVER (ORDER BY quantity) AS quantity_percent_rank FROM inventory WHERE product_id IN (1, 3, 9, 10)) SELECT s.id, s.product_id, s.last_restock, s.quantity_bucket, s.quantity_percent_rank, (SELECT AVG(t2.unit_price) FROM order_items t2 WHERE t2.product_id = s.product_id) AS avg_order_item_unit_price FROM enriched s ORDER BY quantity_percent_rank DESC, product_id DESC
